// Corner - the logo as two pictures, a light one and a dark one, for the places that show it while the app runs:
// the tray, the taskbar in Full Mode and the start-up animation (Launch.cs). The light one shows while Windows is in
// light mode and the dark one while it is in dark mode. The file icon of Corner.exe (src\corner.ico) is the light one.
// Both are 160 px, trimmed to the mark, and made by design\logo-sunburst\logo_two.py; do not edit the text by hand.
using System;
using System.IO;
using System.Windows;
using System.Windows.Interop;
using System.Windows.Media.Imaging;

namespace Corner
{
    static class Logo
    {
        public static bool Dark; // which one is showing; set by Shell.ApplyLogo
        static BitmapSource light, dark;

        public static BitmapSource Image
        {
            get
            {
                if (Dark) { if (dark == null) dark = Decode(PngDark); return dark; }
                if (light == null) light = Decode(PngLight);
                return light;
            }
        }

        static BitmapSource Decode(string[] png)
        {
            var d = new PngBitmapDecoder(new MemoryStream(Convert.FromBase64String(string.Concat(png))), BitmapCreateOptions.PreservePixelFormat, BitmapCacheOption.OnLoad);
            var f = d.Frames[0]; f.Freeze();
            return f;
        }

        /// The picture in use as an icon for the tray, 32 px.
        public static System.Drawing.Icon Icon()
        {
            using (var big = new System.Drawing.Bitmap(new MemoryStream(Convert.FromBase64String(string.Concat(Dark ? PngDark : PngLight)))))
            using (var small = new System.Drawing.Bitmap(32, 32, System.Drawing.Imaging.PixelFormat.Format32bppArgb))
            {
                using (var g = System.Drawing.Graphics.FromImage(small))
                {
                    g.InterpolationMode = System.Drawing.Drawing2D.InterpolationMode.HighQualityBicubic;
                    g.PixelOffsetMode = System.Drawing.Drawing2D.PixelOffsetMode.HighQuality;
                    g.DrawImage(big, new System.Drawing.Rectangle(0, 0, 32, 32));
                }
                return System.Drawing.Icon.FromHandle(small.GetHicon());
            }
        }

        /// Windows' own setting for apps (Settings > Personalisation > Colours). A test run can force it with CORNER_DARK.
        public static bool WindowsIsDark()
        {
            string forced = Environment.GetEnvironmentVariable("CORNER_DARK");
            if (Environment.GetEnvironmentVariable("CORNER_DATA") != null && forced != null) return forced == "1";
            try
            {
                object v = Microsoft.Win32.Registry.GetValue(@"HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize", "AppsUseLightTheme", 1);
                return v is int && (int)v == 0;
            }
            catch { return false; }
        }

        static readonly string[] PngLight =
        {
            "",
            "",
            "",
            "",
            "",
            "",
