            "",
            "",
            "iYz//DiGN9WAxfZ1PHz4MG/cuPFpEXBP6wB8gsDEFVdcQVdccYVdF/25PjZu3JgLMC1cuJAcaTrevBnYuBF9xZp+HR8bzZN5ouewceNGvuKKK3Lh76djoP26g5zmCixmpl93cP+6n8N/5I//H7NG3B53NA8XAAAAAElFTkSuQmCC",
        };
    }

    partial class Shell
    {
        /// Shows the logo that goes with Windows' mode, in the tray and (when it is open) on the Full Mode window.
        /// Called at start and then every ten seconds, so a change of mode is picked up without a restart.
        void ApplyLogo(bool first)
        {
            bool dark = Logo.WindowsIsDark();
            if (!first && dark == Logo.Dark) return;
            Logo.Dark = dark;
            try
            {
                tray.Icon = Logo.Icon();
                Icon = full ? Imaging.CreateBitmapSourceFromHIcon(tray.Icon.Handle, Int32Rect.Empty, BitmapSizeOptions.FromEmptyOptions()) : null; // (null: made again when Full Mode opens)
            }
            catch (Exception ex) { Store.Log(ex); }
        }
    }
}
